#!/usr/bin/env python3
"""zoxide - A smarter cd command for your terminal."""

import argparse
import os
import sys
import re
import time
import json
import glob as glob_module
from pathlib import Path

VERSION = "0.9.9"
AUTHOR = "Ajeet D'Souza <98ajeet@gmail.com>"
URL = "https://github.com/ajeetdsouza/zoxide"

def get_data_dir():
    if os.name == 'nt':
        localappdata = os.environ.get('LOCALAPPDATA', os.path.expanduser('~\\AppData\\Local'))
        return os.path.join(localappdata, 'zoxide')
    else:
        xdg_data_home = os.environ.get('XDG_DATA_HOME', os.path.expanduser('~/.local/share'))
        return os.path.join(xdg_data_home, 'zoxide')

ZO_DATA_DIR = os.environ.get('_ZO_DATA_DIR')
ZO_ECHO = os.environ.get('_ZO_ECHO', '0')
ZO_EXCLUDE_DIRS = os.environ.get('_ZO_EXCLUDE_DIRS', '')
ZO_FZF_OPTS = os.environ.get('_ZO_FZF_OPTS', '')
ZO_MAXAGE = int(os.environ.get('_ZO_MAXAGE', '10000'))
ZO_RESOLVE_SYMLINKS = os.environ.get('_ZO_RESOLVE_SYMLINKS', '0')

def get_db_path():
    if ZO_DATA_DIR:
        return os.path.join(ZO_DATA_DIR, 'db')
    return get_data_dir()

def resolve_symlink(path):
    if ZO_RESOLVE_SYMLINKS == '1':
        try:
            return os.path.realpath(path)
        except (OSError, ValueError):
            return path
    return path

def should_exclude(path):
    if not ZO_EXCLUDE_DIRS:
        return False
    home = os.path.expanduser('~')
    if path == home or path.startswith(home + os.sep):
        return True
    if os.name == 'nt':
        patterns = ZO_EXCLUDE_DIRS.split(';')
    else:
        patterns = ZO_EXCLUDE_DIRS.split(':')
    for pattern in patterns:
        pattern = pattern.strip()
        if not pattern:
            continue
        if pattern.endswith('/*'):
            prefix = pattern[:-2]
            if path.startswith(prefix):
                return True
        elif pattern.endswith('*'):
            prefix = pattern[:-1]
            if path.startswith(prefix):
                return True
        elif path == pattern or path.startswith(pattern + os.sep):
            return True
    return False

def load_db():
    db_path = get_db_path()
    if not os.path.exists(db_path):
        return {}
    entries = {}
    with open(db_path, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            parts = line.split()
            if len(parts) >= 3:
                try:
                    path = parts[0]
                    score = int(parts[1])
                    timestamp = int(parts[2])
                    entries[path] = {'score': score, 'timestamp': timestamp}
                except ValueError:
                    continue
    return entries

def save_db(entries):
    db_path = get_db_path()
    os.makedirs(os.path.dirname(db_path), exist_ok=True)
    with open(db_path, 'w') as f:
        for path, data in sorted(entries.items(), key=lambda x: x[1]['timestamp'], reverse=True):
            f.write(f"{path} {data['score']} {data['timestamp']}\n")

def add_directory(path, score=None):
    path = resolve_symlink(path)
    if should_exclude(path):
        return
    if score is None:
        score = 1
    db = load_db()
    if path in db:
        db[path]['score'] += score
        db[path]['timestamp'] = int(time.time())
    else:
        db[path] = {'score': score, 'timestamp': int(time.time())}
    save_db(db)

def query_directory(args):
    query = ' '.join(args.query)
    exclude = args.exclude
    db = load_db()
    if not db:
        print("zoxide: no match found", file=sys.stderr)
        return 1
    if exclude:
        db = {k: v for k, v in db.items() if k != exclude}
    if query:
        query_parts = query.split()
        matching = []
        for path, data in db.items():
            path_lower = path.lower()
            if all(q.lower() in path_lower for q in query_parts):
                matching.append((path, data))
        if not matching:
            print("zoxide: no match found", file=sys.stderr)
            return 1
    else:
        matching = list(db.items())
    matching.sort(key=lambda x: (x[1]['score'], x[1]['timestamp']), reverse=True)
    result = matching[0][0]
    if ZO_ECHO == '1':
        print(result)
    return 0

def remove_directory(path):
    db = load_db()
    if path not in db:
        print(f"zoxide: path not found in database: {path}", file=sys.stderr)
        return 1
    del db[path]
    save_db(db)
    return 0

def main():
    parser = argparse.ArgumentParser(description='A smarter cd command for your terminal.')
    subparsers = parser.add_subparsers(dest='command', help='Commands')

    add_parser = subparsers.add_parser('add', help='Add a directory to the database.')
    add_parser.add_argument('path', nargs='?', help='Path to add')
    add_parser.add_argument('-s', '--score', type=int, default=1, help='Score to add')

    query_parser = subparsers.add_parser('query', help='Query the database for a directory.')
    query_parser.add_argument('query', nargs='*', help='Query string')
    query_parser.add_argument('-e', '--exclude', help='Exclude path')
    query_parser.add_argument('-E', '--echo', action='store_true', help='Echo result')

    remove_parser = subparsers.add_parser('remove', help='Remove a directory from the database.')
